import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Activity, AlertTriangle, Boxes, CheckCircle2, FileCheck2, Link2, PackageOpen, ShieldCheck } from 'lucide-react';
import type { RevenueOpsSnapshot } from '../shared/revenue-ops-contracts';
import type { RetailCertificationPack } from '../shared/retail-certification-pack-contracts';
import type {
  ApplyRetailPurchaseOcrMappingInput,
  ConfigureRetailOcrProviderInput,
  CreateRetailCommerceConformanceCaseInput,
  CreateRetailCommerceCatalogMappingInput,
  DisableRetailCommerceCatalogMappingInput,
  HandoffRetailCommerceOrderInput,
  CreateRetailSettlementAllocationPackInput,
  DecideRetailSettlementAllocationPackInput,
  CreateRetailCommerceConflictResolutionInput,
  DecideRetailCommerceConflictResolutionInput,
  CreateRetailSettlementWithholdingEvidenceInput,
  DecideRetailSettlementWithholdingEvidenceInput,
  PrepareRetailSettlementJournalInput,
  CreateRetailOcrProviderProfileInput,
  ExecuteRetailOcrInput,
  ExecuteRetailCommercePushInput,
  DecideRetailCommercePushInput,
  LinkRetailCommerceReturnInput,
  PlanRetailCommerceConformancePackInput,
  PrepareRetailCommercePushInput,
  PrepareRetailPurchaseOcrMappingInput,
  RecordRetailCommerceConformanceInput,
  ResolveRetailPurchaseExceptionInput,
  ScanRetailPurchaseExceptionsInput,
  RetailCommerceOrder,
  RetailOcrDocumentKind,
  ReserveRetailCommerceOrderInput,
  TestRetailOcrProviderInput,
  TransitionRetailCommerceOrderInput,
} from '../shared/retail-commerce-contracts';
import { computeRetailChannelHealth } from '../domain/retail-channel-health';
import { computeRetailChannelSettlementReadiness, computeRetailMarketplacePayoutReconciliation, computeRetailSettlementExceptionTriage } from '../domain/retail-reports';
import { RetailReplenishmentPlanner } from './RetailReplenishmentPlanner';
import { RetailLossPreventionPanel } from './RetailLossPreventionPanel';
import { RetailOmnichannelOrderDesk } from './RetailOmnichannelOrderDesk';

const message = (error: unknown) => error instanceof Error ? error.message : 'Retail ecosystem action could not be completed.';

type EvidenceActionFormProps = {
  label: string;
  placeholder: string;
  buttonLabel: string;
  busy: boolean;
  disabled?: boolean;
  onSubmit: (evidence: string) => void;
};

function EvidenceActionForm({ label, placeholder, buttonLabel, busy, disabled = false, onSubmit }: EvidenceActionFormProps): ReactNode {
  return <form className="retail-evidence-action" onSubmit={(event) => {
    event.preventDefault();
    const evidence = String(new FormData(event.currentTarget).get('evidence') ?? '').trim();
    if (evidence) onSubmit(evidence);
  }}>
    <label>{label}<input name="evidence" placeholder={placeholder} minLength={4} required /></label>
    <button type="submit" disabled={busy || disabled}>{buttonLabel}</button>
  </form>;
}

type Props = {
  revenue: RevenueOpsSnapshot;
  busy: boolean;
  activeActorId: string;
  onCreateOcrProviderProfile?: (input: CreateRetailOcrProviderProfileInput) => Promise<void>;
  onConfigureOcrProvider?: (input: ConfigureRetailOcrProviderInput) => Promise<void>;
  onExecuteOcr?: (input: ExecuteRetailOcrInput) => Promise<void>;
  onTestOcrProvider?: (input: TestRetailOcrProviderInput) => Promise<void>;
  onPrepareOcrMapping?: (input: PrepareRetailPurchaseOcrMappingInput) => Promise<void>;
  onApplyOcrMapping?: (input: ApplyRetailPurchaseOcrMappingInput) => Promise<void>;
  onPreparePushBatch?: (input: PrepareRetailCommercePushInput) => Promise<void>;
  onDecidePushBatch?: (input: DecideRetailCommercePushInput) => Promise<void>;
  onExecutePushBatch?: (input: ExecuteRetailCommercePushInput) => Promise<void>;
  onCreateCatalogMapping?: (input: CreateRetailCommerceCatalogMappingInput) => Promise<void>;
  onDisableCatalogMapping?: (input: DisableRetailCommerceCatalogMappingInput) => Promise<void>;
  onHandoffOrder?: (input: HandoffRetailCommerceOrderInput) => Promise<void>;
  onReserveOrder?: (input: ReserveRetailCommerceOrderInput) => Promise<void>;
  onCreateSettlementAllocationPack?: (input: CreateRetailSettlementAllocationPackInput) => Promise<void>;
  onDecideSettlementAllocationPack?: (input: DecideRetailSettlementAllocationPackInput) => Promise<void>;
  onCreateConflictResolution?: (input: CreateRetailCommerceConflictResolutionInput) => Promise<void>;
  onDecideConflictResolution?: (input: DecideRetailCommerceConflictResolutionInput) => Promise<void>;
  onCreateWithholdingEvidence?: (input: CreateRetailSettlementWithholdingEvidenceInput) => Promise<void>;
  onDecideWithholdingEvidence?: (input: DecideRetailSettlementWithholdingEvidenceInput) => Promise<void>;
  onPrepareSettlementJournal?: (input: PrepareRetailSettlementJournalInput) => Promise<void>;
  onTransitionOrder?: (input: TransitionRetailCommerceOrderInput) => Promise<void>;
  onLinkReturn?: (input: LinkRetailCommerceReturnInput) => Promise<void>;
  onCreateConformanceCase?: (input: CreateRetailCommerceConformanceCaseInput) => Promise<void>;
  onPlanConformancePack?: (input: PlanRetailCommerceConformancePackInput) => Promise<void>;
  onRecordConformance?: (input: RecordRetailCommerceConformanceInput) => Promise<void>;
  onScanPurchaseExceptions?: (input: ScanRetailPurchaseExceptionsInput) => Promise<void>;
  onResolvePurchaseException?: (input: ResolveRetailPurchaseExceptionInput) => Promise<void>;
};

export function RetailCommerceAdvancedWorkbench({ revenue, busy, activeActorId, onCreateOcrProviderProfile, onConfigureOcrProvider, onExecuteOcr, onTestOcrProvider, onPrepareOcrMapping, onApplyOcrMapping, onPreparePushBatch, onDecidePushBatch, onExecutePushBatch, onCreateCatalogMapping, onDisableCatalogMapping, onHandoffOrder, onReserveOrder, onCreateSettlementAllocationPack, onDecideSettlementAllocationPack, onCreateConflictResolution, onDecideConflictResolution, onCreateWithholdingEvidence, onDecideWithholdingEvidence, onPrepareSettlementJournal, onTransitionOrder, onLinkReturn, onCreateConformanceCase, onPlanConformancePack, onRecordConformance, onScanPurchaseExceptions, onResolvePurchaseException }: Props): ReactNode {
  const [notice, setNotice] = useState('');
  const [certificationPack, setCertificationPack] = useState<RetailCertificationPack | null>(null);
  useEffect(() => {
    let active = true;
    void window.epicBos.integration.getRetailCertificationPack().then((pack) => { if (active) setCertificationPack(pack); }).catch(() => { if (active) setCertificationPack(null); });
    return () => { active = false; };
  }, [revenue.revision]);
  const firstVariant = revenue.itemVariants.find((item) => item.active);
  const firstConnector = revenue.retailCommerceConnectors[0];
  const certifiedOcrProviders = revenue.retailOcrProviderProfiles.filter((profile) => profile.mode === 'api' && profile.status === 'certified' && profile.credentialStatus === 'configured');
  const firstPurchaseOrder = revenue.purchaseOrders.find((order) => order.lines.length > 0);
  const show = async (action: (() => Promise<void>) | undefined, success: string) => {
    if (!action) return;
    try { await action(); setNotice(success); } catch (error) { setNotice(message(error)); }
  };
  const submit = async (event: FormEvent<HTMLFormElement>, action: (data: FormData) => Promise<void>) => { event.preventDefault(); await action(new FormData(event.currentTarget)); };
  const activeOrders = revenue.retailCommerceOrders.slice(0, 12);
  const channelHealth = useMemo(() => computeRetailChannelHealth({
    connectors: revenue.retailCommerceConnectors,
    syncRuns: revenue.retailCommerceSyncRuns,
    orders: revenue.retailCommerceOrders,
    settlements: revenue.retailSettlementReconciliations,
    resolutions: revenue.retailCommerceConflictResolutions,
  }), [revenue.retailCommerceConnectors, revenue.retailCommerceSyncRuns, revenue.retailCommerceOrders, revenue.retailSettlementReconciliations, revenue.retailCommerceConflictResolutions]);
  const marketplacePayouts = useMemo(() => revenue.retailSettlementReconciliations.slice(0, 12).map((settlement) => computeRetailMarketplacePayoutReconciliation({
    settlement,
    orders: revenue.retailCommerceOrders,
    allocation: revenue.retailSettlementAllocationPacks.find((pack) => pack.settlementId === settlement.id),
  })), [revenue.retailSettlementReconciliations, revenue.retailCommerceOrders, revenue.retailSettlementAllocationPacks]);
  const settlementReadiness = useMemo(() => computeRetailChannelSettlementReadiness({
    connectors: revenue.retailCommerceConnectors,
    settlements: revenue.retailSettlementReconciliations,
    allocations: revenue.retailSettlementAllocationPacks,
    withholding: revenue.retailSettlementWithholdingEvidence,
    conflicts: revenue.retailCommerceConflictResolutions,
    orders: revenue.retailCommerceOrders,
    fromDate: '1900-01-01',
    toDate: '2999-12-31',
  }), [revenue.retailCommerceConnectors, revenue.retailSettlementReconciliations, revenue.retailSettlementAllocationPacks, revenue.retailSettlementWithholdingEvidence, revenue.retailCommerceConflictResolutions, revenue.retailCommerceOrders]);
  const settlementTriage = useMemo(() => computeRetailSettlementExceptionTriage(settlementReadiness), [settlementReadiness]);
  const suggestedNext = (order: RetailCommerceOrder): RetailCommerceOrder['status'][] => order.status === 'imported' ? ['confirmed', 'cancelled'] : order.status === 'confirmed' ? ['fulfilled', 'return-requested', 'rto'] : order.status === 'fulfilled' ? ['return-requested', 'returned', 'rto'] : order.status === 'return-requested' ? ['returned', 'rto'] : [];
  return <section className="retail-returns-workbench__settlement-panel">
    <header><div><span>09 / Provider control plane</span><h4>Certified OCR, push payloads and order lifecycle</h4></div><ShieldCheck size={19} aria-hidden="true" /></header>
    <p className="retail-returns-workbench__settlement-intro">Every provider action is prepared locally, checksummed, and independently evidenced. ONDC and marketplace systems remain authoritative for real submission, delivery, refund and RTO outcomes.</p>
    <RetailOmnichannelOrderDesk revenue={revenue} />
    <form className="retail-exchange-form" onSubmit={(event) => { event.preventDefault(); const data = new FormData(event.currentTarget); const connectorId = String(data.get('connectorId')); void show(onPlanConformancePack ? () => onPlanConformancePack({ connectorId, suiteName: String(data.get('suiteName')), suiteVersion: String(data.get('suiteVersion')) }) : undefined, 'Complete provider capability pack planned; independent evidence is still required.'); }}>
      <div><label>Connector<select name="connectorId" required><option value="">Choose marketplace / ONDC connector</option>{revenue.retailCommerceConnectors.map((connector) => <option key={connector.id} value={connector.id}>{connector.code} · {connector.channel} · {connector.environment}</option>)}</select></label><label>Test pack name<input name="suiteName" defaultValue="India retail capability pack" required /></label><label>Version<input name="suiteVersion" defaultValue="1.0" required /></label><button type="submit" disabled={busy || !onPlanConformancePack || !revenue.retailCommerceConnectors.length}>Plan complete capability pack</button></div>
      <small>Creates one test case for every declared capability. It does not activate a connector or claim provider certification.</small>
    </form>
    <section className="retail-commerce-health" aria-label="Channel conflict and reconciliation queue">
      <header><div><span><Activity size={14} /> CHANNEL HEALTH</span><h4>Conflict &amp; reconciliation queue</h4></div><strong>{channelHealth.openConflictCount} open</strong></header>
      <div className="retail-exchange-form__row">
        <div><strong>Connectors</strong><small>{channelHealth.certifiedConnectorCount}/{channelHealth.connectorCount} credentialed and certified</small></div>
        <div><strong>Sync runs</strong><small>{channelHealth.syncRunCount} recorded · rejected records stay visible</small></div>
        <div><strong>Remote orders</strong><small>{channelHealth.orderCount} imported · return/RTO evidence is explicit</small></div>
        <div><strong>Settlement variance</strong><small>₹{channelHealth.settlementVarianceTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 })} under review</small></div>
      </div>
      {channelHealth.conflicts.length ? <div className="retail-returns-workbench__history-list">{channelHealth.conflicts.slice(0, 12).map((conflict) => <div key={conflict.id} data-status={conflict.severity}><div><strong><AlertTriangle size={13} /> {conflict.title}</strong><small>{conflict.detail}</small><small>Next: {conflict.suggestedAction}</small></div><em>{conflict.severity}</em><EvidenceActionForm label="Independent conflict-review evidence" placeholder="Actual provider/source reference and reviewer note" buttonLabel="Prepare resolution" busy={busy} disabled={!onCreateConflictResolution} onSubmit={(evidence) => void show(() => onCreateConflictResolution!({ conflictId: conflict.id, kind: conflict.kind, sourceId: conflict.sourceId, connectorId: conflict.connectorId, decision: conflict.kind.startsWith('sync-') ? 'retry' : 'accepted', evidence }), 'Conflict resolution pack prepared for independent approval.')} /></div>)}</div> : <p className="retail-returns-workbench__empty"><CheckCircle2 size={14} /> No unresolved channel conflicts in the current evidence scope.</p>}
      {revenue.retailCommerceConflictResolutions.filter((resolution) => resolution.status === 'prepared').slice(0, 8).map((resolution) => <div className="retail-returns-workbench__history-list" key={resolution.id}><div><strong>{resolution.decision} · {resolution.kind}</strong><small>{resolution.evidence}</small></div>{resolution.requestedBy !== activeActorId ? <EvidenceActionForm label="Independent approval evidence" placeholder="Actual review record or source reference" buttonLabel="Approve resolution" busy={busy} disabled={!onDecideConflictResolution} onSubmit={(evidence) => void show(() => onDecideConflictResolution!({ id: resolution.id, decision: 'approved', evidence, expectedVersion: resolution.version }), 'Conflict resolution approved and removed from the active queue.')} /> : <em>Awaiting independent reviewer</em>}</div>)}
    </section>
    <section className="retail-commerce-health" aria-label="Production certification readiness">{certificationPack ? <><header><div><span><ShieldCheck size={14} /> PRODUCTION GATE</span><h4>Provider and device readiness</h4></div><strong data-status={certificationPack.summary.readyForProduction ? 'ready' : 'attention'}>{certificationPack.summary.readyForProduction ? 'READY' : `${certificationPack.summary.externalGateCount} GATES`}</strong></header><div className="retail-exchange-form__row"><div><strong>Commerce connectors</strong><small>{certificationPack.summary.connectorReadyCount}/{certificationPack.summary.connectorCount} ready · {certificationPack.summary.missingCapabilityCount} capability gaps</small></div><div><strong>Provider adapters</strong><small>{certificationPack.summary.providerReadyCount}/{certificationPack.summary.providerCount} ready · {certificationPack.summary.unresolvedSubmissionCount} open handoffs</small></div><div><strong>Credential rotations</strong><small>{certificationPack.summary.staleCredentialCaseCount} evidence case{certificationPack.summary.staleCredentialCaseCount === 1 ? '' : 's'} must be replayed</small></div><div><strong>Device evidence</strong><small>{certificationPack.summary.devicePreparedCount} prepared · {certificationPack.summary.deviceFailedCount} failed</small></div><div><strong>Preflight history</strong><small>{certificationPack.summary.preflightSuccessCount} passed · {certificationPack.summary.preflightFailureCount} failed</small></div></div><div className="retail-returns-workbench__history-list">{certificationPack.connectors.slice(0, 8).map((connector) => <div key={connector.id}><div><strong>{connector.code} · {connector.channel}</strong><small>{connector.environment} · {connector.nextAction.replaceAll('-', ' ')} · {connector.staleCredentialCaseCount ? `${connector.staleCredentialCaseCount} stale evidence case${connector.staleCredentialCaseCount === 1 ? '' : 's'} · ` : ''}{connector.missingCapabilities.length ? `missing ${connector.missingCapabilities.join(', ')}` : 'capabilities evidenced'}</small></div><em data-status={connector.nextAction === 'ready' ? 'ready' : 'attention'}>{connector.nextAction}</em></div>)}{certificationPack.providers.slice(0, 8).map((provider) => <div key={provider.id}><div><strong>{provider.code} · {provider.domain}</strong><small>{provider.environment} · {provider.nextAction.replaceAll('-', ' ')} · {provider.staleCredentialCaseCount ? `${provider.staleCredentialCaseCount} stale evidence case${provider.staleCredentialCaseCount === 1 ? '' : 's'} · ` : ''}{provider.missingCapabilities.length ? `missing ${provider.missingCapabilities.join(', ')}` : 'capabilities evidenced'}</small></div><em data-status={provider.nextAction === 'ready' ? 'ready' : 'attention'}>{provider.nextAction}</em></div>)}</div><p className="retail-returns-workbench__settlement-intro">This is a local evidence projection. “Ready” never means ONDC, WhatsApp, a bank, or a government portal accepted a request; external certification remains authoritative.</p></> : <p className="retail-returns-workbench__empty">Loading the current certification evidence from the secure main process…</p>}</section>
    <section className="retail-commerce-health" aria-label="Resolved channel outcomes"><header><div><span><CheckCircle2 size={14} /> RESOLVED OUTCOMES</span><h4>What was decided, and on which source</h4></div><strong>{revenue.retailCommerceConflictResolutions.filter((resolution) => resolution.status === 'approved').length} approved</strong></header><div className="retail-returns-workbench__history-list">{revenue.retailCommerceSyncRuns.filter((run) => run.channelConflictResolutionId).slice(0, 6).map((run) => <div key={`sync-outcome-${run.id}`}><div><strong>{run.number} · {run.channelConflictDecision}</strong><small>{run.kind} cursor {run.remoteCursor ?? 'not supplied'} · {run.channelConflictResolutionEvidence}</small></div><em data-status="approved">recorded</em></div>)}{revenue.retailCommerceOrders.filter((order) => order.channelConflictResolutionId).slice(0, 6).map((order) => <div key={`order-outcome-${order.id}`}><div><strong>{order.orderNumber} · {order.channelConflictDecision}</strong><small>Remote order source · {order.channelConflictResolutionEvidence}</small></div><em data-status="approved">recorded</em></div>)}{revenue.retailSettlementReconciliations.filter((settlement) => settlement.channelConflictResolutionId).slice(0, 6).map((settlement) => <div key={`settlement-outcome-${settlement.id}`}><div><strong>{settlement.settlementReference} · {settlement.channelConflictDecision}</strong><small>Settlement source · {settlement.channelConflictResolutionEvidence}</small></div><em data-status="approved">recorded</em></div>)}{!revenue.retailCommerceSyncRuns.some((run) => run.channelConflictResolutionId) && !revenue.retailCommerceOrders.some((order) => order.channelConflictResolutionId) && !revenue.retailSettlementReconciliations.some((settlement) => settlement.channelConflictResolutionId) ? <p className="retail-returns-workbench__empty">Approved channel decisions will appear here with their source evidence.</p> : null}</div></section>
    <section className="retail-commerce-health" aria-label="Marketplace payout reconciliation"><header><div><span><Activity size={14} /> MARKETPLACE PAYOUTS</span><h4>Commission, returns and RTO in one close view</h4></div><strong>{marketplacePayouts.filter((item) => item.status === 'ready-to-close').length}/{marketplacePayouts.length} ready</strong></header><p className="retail-returns-workbench__settlement-intro">Marketplace fee is shown as provider commission. Refunds are split between customer returns and RTO, and a payout is never treated as closed until every linked order has terminal and GST/inventory evidence.</p>{marketplacePayouts.length ? <div className="retail-returns-workbench__history-list">{marketplacePayouts.map((item) => <div key={item.settlementId} data-status={item.status === 'ready-to-close' ? 'ready' : 'attention'}><div><strong>{item.settlementReference} · {item.status === 'ready-to-close' ? 'ready to close' : 'needs action'}</strong><small>Provider payout ₹{item.providerNetAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })} · commission ₹{item.providerCommissionAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })} · refund ₹{item.providerRefundAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</small><small>{item.lifecycle.fulfilled} fulfilled · {item.lifecycle.returned} returned · {item.lifecycle.rto} RTO · {item.lifecycle.open} open · allocation {item.allocationCoveragePct}%</small>{item.nextActions.slice(0, 2).map((action) => <small key={action}>Next: {action}</small>)}</div><em data-status={item.status === 'ready-to-close' ? 'ready' : 'attention'}>{item.rtoRefundAmount > 0 ? `RTO ₹${item.rtoRefundAmount.toLocaleString('en-IN')}` : 'No RTO refund'}</em></div>)}</div> : <p className="retail-returns-workbench__empty">No marketplace payouts are in the current evidence scope.</p>}</section>
    <section className="retail-commerce-health" aria-label="Settlement exception triage"><header><div><span><AlertTriangle size={14} /> SETTLEMENT TRIAGE</span><h4>What blocks money close</h4></div><strong>{settlementTriage.urgentCount} urgent · {settlementTriage.externalCount} external</strong></header><p className="retail-returns-workbench__settlement-intro">One decision queue over the existing payout, allocation, tax, journal, conflict, and order evidence. Amounts are INR exposure only; the queue never creates a second accounting record.</p>{settlementTriage.items.length ? <div className="retail-returns-workbench__history-list">{settlementTriage.items.slice(0, 12).map((item) => <div key={item.id} data-status={item.priority}><div><strong>{item.settlementReference} · {item.kind.replaceAll('-', ' ')}</strong><small>Owner: {item.owner} · route: {item.route} · {item.amount > 0 ? `₹${item.amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })} exposure` : 'no local amount assigned'}</small><small>Next: {item.action}</small></div><em data-status={item.blockedByExternal ? 'external' : item.priority}>{item.blockedByExternal ? 'external hold' : item.priority}</em></div>)}</div> : <p className="retail-returns-workbench__empty"><CheckCircle2 size={14} /> No settlement exceptions in the current local evidence scope.</p>}</section>
    <RetailReplenishmentPlanner revenue={revenue} />
    <RetailLossPreventionPanel revenue={revenue} />
    <div className="retail-exchange-form__row">
      <div><strong><ShieldCheck size={15} /> Document-kind replay evidence</strong><p className="retail-returns-workbench__settlement-intro">Every declared OCR path needs its own independently assessed replay. Legacy aggregate tests do not close credit-note or debit-note gates.</p>{revenue.retailOcrProviderProfiles.slice(0, 8).flatMap((profile) => profile.supportedDocumentKinds.map((documentKind) => { const evidence = profile.testEvidenceByDocumentKind?.[documentKind]; return <div className="retail-returns-workbench__history-list" key={`${profile.id}-${documentKind}`}><div><strong>{profile.code} · {documentKind}</strong><small>{evidence ? `assessed by ${evidence.testedBy} · ${evidence.testedAt}` : 'kind-level evidence missing'}</small></div>{profile.credentialStatus === 'configured' && profile.createdBy !== activeActorId && !evidence ? <form onSubmit={(event) => void submit(event, async (data) => show(onTestOcrProvider ? () => onTestOcrProvider!({ id: profile.id, documentKind: String(data.get('documentKind')) as RetailOcrDocumentKind, evidence: String(data.get('evidence')), expectedVersion: profile.version }) : undefined, 'OCR document-kind certification evidence recorded.'))}><input type="hidden" name="documentKind" value={documentKind} /><input name="evidence" placeholder={`Real ${documentKind} replay reference`} required /><button type="submit" disabled={busy || !onTestOcrProvider}>Record evidence</button></form> : evidence ? <em>Evidence recorded</em> : <em>Configure credentials</em>}</div>; }))}</div>
      <form onSubmit={(event) => void submit(event, async (data) => show(onCreateCatalogMapping ? () => onCreateCatalogMapping({ connectorId: String(data.get('connectorId')), remoteSku: String(data.get('remoteSku')), itemVariantId: String(data.get('variantId')), remoteTitle: String(data.get('remoteTitle')) || undefined }) : undefined, 'Remote SKU mapping created; channel orders and pushes are now identity-safe.'))}>
        <strong><Link2 size={15} /> Marketplace / ONDC SKU mapping</strong><label>Connector<select name="connectorId" required>{revenue.retailCommerceConnectors.filter((connector) => connector.credentialStatus === 'configured').map((connector) => <option key={connector.id} value={connector.id}>{connector.code} · {connector.channel}</option>)}</select></label><label>Remote SKU<input name="remoteSku" placeholder="ONDC-TEA-1KG" required /></label><label>Local SKU<select name="variantId" required><option value="">Choose SKU</option>{revenue.itemVariants.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.sku} · {item.name}</option>)}</select></label><label>Remote title<input name="remoteTitle" placeholder="Optional channel title" /></label><button className="button button--primary" disabled={busy || !onCreateCatalogMapping}>Save mapping</button>
      </form>
      <div><strong><Link2 size={15} /> Mapping registry</strong>{revenue.retailCommerceCatalogMappings.slice(0, 12).map((mapping) => <div className="retail-returns-workbench__history-list" key={mapping.id}><div><strong>{mapping.remoteSku} → {revenue.itemVariants.find((item) => item.id === mapping.itemVariantId)?.sku ?? 'unknown'} · {mapping.status}</strong><small>{revenue.retailCommerceConnectors.find((connector) => connector.id === mapping.connectorId)?.code ?? 'connector'} · v{mapping.version}</small></div>{mapping.status === 'active' && mapping.createdBy !== activeActorId ? <EvidenceActionForm label="Independent catalogue review evidence" placeholder="Actual channel SKU retirement or replacement reference" buttonLabel="Disable mapping" busy={busy} disabled={!onDisableCatalogMapping} onSubmit={(evidence) => void show(() => onDisableCatalogMapping!({ id: mapping.id, expectedVersion: mapping.version, evidence }), 'Remote SKU mapping disabled with evidence.')} /> : null}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <form onSubmit={(event) => void submit(event, async (data) => show(onCreateOcrProviderProfile ? () => onCreateOcrProviderProfile({ code: String(data.get('code')), name: String(data.get('name')), mode: String(data.get('mode')) as CreateRetailOcrProviderProfileInput['mode'], baseUrl: String(data.get('baseUrl')) || undefined, supportedDocumentKinds: ['supplier-invoice'] }) : undefined, 'OCR provider profile created; configure and certify it before intake.'))}>
        <strong><FileCheck2 size={15} /> OCR provider profile</strong><label>Provider code<input name="code" defaultValue="MANUAL-OCR" required /></label><label>Display name<input name="name" defaultValue="India supplier invoice OCR" required /></label><label>Mode<select name="mode"><option value="manual">Manual review</option><option value="api">API adapter</option></select></label><label>HTTPS origin for API mode<input name="baseUrl" type="url" placeholder="https://ocr-provider.example" /></label><button className="button button--primary" disabled={busy || !onCreateOcrProviderProfile}>Create profile</button>
      </form>
      <div><strong><ShieldCheck size={15} /> Provider certification</strong>{revenue.retailOcrProviderProfiles.slice(0, 8).map((profile) => <div className="retail-returns-workbench__history-list" key={profile.id}><div><strong>{profile.code} · {profile.status}</strong><small>{profile.credentialStatus} · {profile.lastTestedAt ?? 'not tested'}</small></div>{profile.status !== 'certified' ? <><form onSubmit={(event) => void submit(event, async (data) => show(onConfigureOcrProvider ? () => onConfigureOcrProvider!({ id: profile.id, credentialFingerprint: String(data.get('fingerprint')) || undefined, clientId: String(data.get('clientId')) || undefined, clientSecret: String(data.get('clientSecret')) || undefined, apiKey: String(data.get('apiKey')) || undefined, bearerToken: String(data.get('bearerToken')) || undefined, signingKey: String(data.get('signingKey')) || undefined }) : undefined, 'OCR credentials sealed in the encrypted main-process vault.'))}><input name="fingerprint" placeholder="Provider SHA-256 fingerprint" inputMode="text" /><input name="clientId" placeholder="Client ID" /><input name="clientSecret" type="password" placeholder="Client secret" /><input name="apiKey" type="password" placeholder="API key" /><input name="bearerToken" type="password" placeholder="Bearer token" /><input name="signingKey" type="password" placeholder="Signing key" /><button type="submit" disabled={busy || !onConfigureOcrProvider}>Seal credentials</button></form>{profile.credentialStatus === 'configured' ? <form onSubmit={(event) => void submit(event, async (data) => show(onTestOcrProvider ? () => onTestOcrProvider!({ id: profile.id, evidence: String(data.get('evidence')), expectedVersion: profile.version }) : undefined, 'OCR provider certification evidence recorded.'))}><input name="evidence" placeholder="Real sandbox replay evidence reference" required /><button type="submit" disabled={busy || !onTestOcrProvider}>Record certification</button></form> : null}</> : <em>Certified</em>}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <form onSubmit={(event) => void submit(event, async (data) => { const [providerId, version] = String(data.get('providerSelection')).split(':'); return show(onExecuteOcr ? () => onExecuteOcr({ providerId: providerId ?? '', method: String(data.get('method')) as ExecuteRetailOcrInput['method'], path: String(data.get('path')), payloadJson: String(data.get('payloadJson')) || undefined, source: String(data.get('source')) as ExecuteRetailOcrInput['source'], fileName: String(data.get('fileName')), fileChecksum: String(data.get('fileChecksum')), expectedProviderVersion: Number(version) }) : undefined, 'Certified OCR response normalized and supplier invoice queued for review.'); })}>
        <strong><FileCheck2 size={15} /> Run certified OCR adapter</strong><label>API provider<select name="providerSelection" required><option value="">Choose certified provider</option>{certifiedOcrProviders.map((profile) => <option key={profile.id} value={`${profile.id}:${profile.version}`}>{profile.code} · v{profile.version}</option>)}</select></label><label>Method<select name="method"><option value="POST">POST</option><option value="GET">GET</option></select></label><label>Relative HTTPS path<input name="path" defaultValue="/v1/invoices/parse" required /></label><label>JSON request body<textarea name="payloadJson" placeholder='{"fileChecksum":"..."}' rows={2} /></label><label>Source<select name="source"><option value="upload">Upload</option><option value="email">Email</option><option value="scan">Scan</option></select></label><label>File name<input name="fileName" defaultValue="supplier-invoice.pdf" required /></label><label>Source file SHA-256<input name="fileChecksum" placeholder="Real source file checksum" required /></label><button className="button button--primary" disabled={busy || !onExecuteOcr}>Run OCR</button>
      </form>
      <form onSubmit={(event) => void submit(event, async (data) => { const document = revenue.retailPurchaseOcrDocuments.find((item) => item.id === String(data.get('documentId'))); const selectedVariant = String(data.get('variantId')); if (!document || !onPrepareOcrMapping || !firstPurchaseOrder) return; await show(() => onPrepareOcrMapping({ ocrDocumentId: document.id, mappings: document.lines.map((line) => ({ ocrLineId: line.id, purchaseOrderLineId: String(data.get(`po-${line.id}`)), itemVariantId: selectedVariant })) }), 'PO-line mapping prepared for independent review.'); })}>
        <strong><Link2 size={15} /> PO-line mapping</strong><label>Approved OCR document<select name="documentId" required><option value="">Choose document</option>{revenue.retailPurchaseOcrDocuments.filter((document) => document.status === 'approved').map((document) => <option key={document.id} value={document.id}>{document.number} · {document.lines.length} lines</option>)}</select></label><label>Item variant<select name="variantId" required><option value="">Choose SKU</option>{revenue.itemVariants.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.sku} · {item.name}</option>)}</select></label>{revenue.retailPurchaseOcrDocuments.filter((document) => document.status === 'approved').slice(0, 1).flatMap((document) => document.lines.map((line) => <label key={line.id}>PO line for {line.description}<select name={`po-${line.id}`} required><option value="">Choose PO line</option>{(firstPurchaseOrder?.lines ?? []).map((poLine) => <option key={poLine.id} value={poLine.id}>{poLine.id.slice(0, 8)} · {poLine.quantity} qty</option>)}</select></label>))}<button className="button button--primary" disabled={busy || !onPrepareOcrMapping || !firstPurchaseOrder}>Prepare mapping</button>
      </form>
      <div><strong><PackageOpen size={15} /> Mapping review queue</strong>{revenue.retailPurchaseOcrMappings.slice(0, 8).map((mapping) => <div className="retail-returns-workbench__history-list" key={mapping.id}><div><strong>{mapping.status} · {mapping.mappings.length} lines</strong><small>{mapping.requestedAt} · maker {mapping.requestedBy.slice(0, 8)}</small></div>{mapping.status === 'prepared' && mapping.requestedBy !== activeActorId ? <EvidenceActionForm label="Independent PO and invoice review evidence" placeholder="Actual PO, SKU, and supplier-invoice evidence reference" buttonLabel="Apply mapping" busy={busy} disabled={!onApplyOcrMapping} onSubmit={(evidence) => void show(() => onApplyOcrMapping!({ id: mapping.id, evidence, expectedVersion: mapping.version }), 'PO-line mapping applied to the approved OCR document.')} /> : null}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <form onSubmit={(event) => void submit(event, async (data) => show(onPreparePushBatch ? () => onPreparePushBatch({ connectorId: String(data.get('connectorId')), kind: String(data.get('kind')) as PrepareRetailCommercePushInput['kind'], itemVariantIds: [String(data.get('variantId'))] }) : undefined, 'Catalog/inventory push payload prepared with checksum.'))}>
        <strong><Boxes size={15} /> Catalog / inventory push</strong><label>Connector<select name="connectorId" required>{revenue.retailCommerceConnectors.filter((connector) => connector.credentialStatus === 'configured').map((connector) => <option key={connector.id} value={connector.id}>{connector.code} · {connector.channel}</option>)}</select></label><label>Payload kind<select name="kind"><option value="catalog">Catalog</option><option value="inventory">Inventory</option></select></label><label>SKU<select name="variantId" required><option value="">Choose SKU</option>{revenue.itemVariants.filter((item) => item.active).map((item) => <option key={item.id} value={item.id}>{item.sku} · {item.name}</option>)}</select></label><button className="button button--primary" disabled={busy || !onPreparePushBatch || !firstConnector || !firstVariant}>Prepare push</button>
      </form>
       <div><strong><CheckCircle2 size={15} /> Push evidence</strong>{revenue.retailCommercePushBatches.slice(0, 8).map((batch) => <div className="retail-returns-workbench__history-list" key={batch.id}><div><strong>{batch.number} · {batch.kind} · {batch.status}</strong><small>{batch.records.length} SKU · {batch.payloadChecksum.slice(0, 12)}</small></div>{batch.status === 'prepared' && batch.requestedBy !== activeActorId ? <><small>{onExecutePushBatch ? 'This payload remains prepared locally. A certified provider adapter is authoritative for submission and its received response.' : 'This payload remains prepared locally. Configure a certified provider adapter before any submission.'}</small><form onSubmit={(event) => void submit(event, async (data) => show(onDecidePushBatch ? () => onDecidePushBatch({ id: batch.id, decision: String(data.get('decision')) as DecideRetailCommercePushInput['decision'], evidence: String(data.get('evidence')), providerPayloadChecksum: String(data.get('providerPayloadChecksum')), responseChecksum: String(data.get('responseChecksum')) || undefined, responseByteLength: Number(data.get('responseByteLength')) || undefined, providerReference: String(data.get('providerReference')) || undefined, expectedVersion: batch.version }) : undefined, 'Received provider response recorded against the checksummed payload.'))}><select name="decision" aria-label={`Push result for ${batch.number}`}><option value="acknowledged">Acknowledged</option><option value="failed">Failed</option></select><input type="hidden" name="providerPayloadChecksum" value={batch.payloadChecksum} /><input name="evidence" placeholder="Real provider reference or failure evidence" required /><input name="providerReference" placeholder="Provider acknowledgement reference (optional for failure)" /><input name="responseChecksum" placeholder="Response SHA-256 (required for acknowledgement)" pattern="[a-fA-F0-9]{64}" maxLength={64} inputMode="text" /><input name="responseByteLength" type="number" min={1} max={1048576} placeholder="Response bytes" /><button type="submit" disabled={busy || !onDecidePushBatch}>Record received provider response</button></form></> : null}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <p className="retail-returns-workbench__settlement-intro">Aggregate settlement refunds are proposed only against returned/RTO orders when the provider order set explains the payout. Proposals stay prepared until an independent reviewer verifies the provider evidence.</p>
      <form onSubmit={(event) => void submit(event, async (data) => show(onCreateSettlementAllocationPack ? () => onCreateSettlementAllocationPack({ settlementId: String(data.get('settlementId')), allocations: [{ orderId: String(data.get('orderId')), grossAmount: Number(data.get('grossAmount')), refundAmount: Number(data.get('refundAmount')), feeAmount: Number(data.get('feeAmount')), taxWithheldAmount: Number(data.get('taxWithheldAmount')), netAmount: Number(data.get('netAmount')) }] }) : undefined, 'Settlement order allocation pack prepared for independent review.'))}>
        <strong><Link2 size={15} /> Settlement order allocation</strong><label>Settlement<select name="settlementId" required><option value="">Choose variance</option>{revenue.retailSettlementReconciliations.filter((settlement) => ['variance-review', 'matched'].includes(settlement.status)).map((settlement) => <option key={settlement.id} value={settlement.id}>{settlement.settlementReference} · ₹{settlement.netAmount.toLocaleString('en-IN')}</option>)}</select></label><label>Order<select name="orderId" required><option value="">Choose order</option>{revenue.retailCommerceOrders.map((order) => <option key={order.id} value={order.id}>{order.orderNumber} · ₹{order.totalAmount.toLocaleString('en-IN')}</option>)}</select></label><label>Gross<input name="grossAmount" type="number" min="0" step="0.01" required /></label><label>Refund<input name="refundAmount" type="number" min="0" step="0.01" defaultValue="0" required /></label><label>Fee<input name="feeAmount" type="number" min="0" step="0.01" defaultValue="0" required /></label><label>TDS/TCS<input name="taxWithheldAmount" type="number" min="0" step="0.01" defaultValue="0" required /></label><label>Net<input name="netAmount" type="number" min="0" step="0.01" required /></label><button className="button button--primary" disabled={busy || !onCreateSettlementAllocationPack}>Prepare allocation</button>
      </form>
      <div><strong><CheckCircle2 size={15} /> Allocation review queue</strong>{revenue.retailSettlementAllocationPacks.slice(0, 10).map((pack) => <div className="retail-returns-workbench__history-list" key={pack.id}><div><strong>{pack.status} · ₹{pack.allocatedNetAmount.toLocaleString('en-IN')} · {pack.allocations.length} orders</strong><small>Settlement {revenue.retailSettlementReconciliations.find((settlement) => settlement.id === pack.settlementId)?.settlementReference ?? pack.settlementId} · checksum {pack.payloadChecksum.slice(0, 12)}</small></div>{pack.status === 'prepared' && pack.requestedBy !== activeActorId ? <EvidenceActionForm label="Independent allocation-review evidence" placeholder="Actual order, refund, fee, and tax reconciliation reference" buttonLabel="Approve allocation" busy={busy} disabled={!onDecideSettlementAllocationPack} onSubmit={(evidence) => void show(() => onDecideSettlementAllocationPack!({ id: pack.id, decision: 'approved', evidence, expectedVersion: pack.version }), 'Settlement allocation pack approved; variance can now be resolved.')} /> : null}</div>)}</div>
    </div>
    <div className="retail-returns-workbench__history-list"><strong><CheckCircle2 size={15} /> Accounting handoff queue</strong>{revenue.retailSettlementReconciliations.filter((settlement) => ['matched', 'resolved'].includes(settlement.status)).slice(0, 10).map((settlement) => { const journal = settlement.journalDraftId ? revenue.journalDrafts.find((draft) => draft.id === settlement.journalDraftId) : undefined; return <div key={settlement.id}><div><strong>{settlement.settlementReference} · {settlement.status}</strong><small>Net ₹{settlement.netAmount.toLocaleString('en-IN')} · {journal ? `journal ${journal.status}` : 'no accounting draft'}</small></div>{!journal ? <button type="button" disabled={busy || !onPrepareSettlementJournal} onClick={() => void show(() => onPrepareSettlementJournal!({ id: settlement.id, expectedVersion: settlement.version }), 'Balanced marketplace settlement journal draft prepared for Finance.')}>Prepare accounting draft</button> : <em data-status={journal.status}>{journal.status}</em>}</div>; })}</div>
    <div className="retail-exchange-form__row">
      <form onSubmit={(event) => void submit(event, async (data) => show(onCreateWithholdingEvidence ? () => onCreateWithholdingEvidence({ settlementId: String(data.get('settlementId')), taxType: String(data.get('taxType')) as CreateRetailSettlementWithholdingEvidenceInput['taxType'], periodFrom: String(data.get('periodFrom')), periodTo: String(data.get('periodTo')), amount: Number(data.get('amount')), certificateReference: String(data.get('certificateReference')), challanReference: String(data.get('challanReference')) || undefined }) : undefined, 'TDS/TCS certificate evidence prepared for independent approval.'))}>
        <strong><FileCheck2 size={15} /> TDS/TCS certificate evidence</strong><label>Settlement<select name="settlementId" required><option value="">Choose withholding settlement</option>{revenue.retailSettlementReconciliations.filter((settlement) => settlement.taxWithheldAmount > 0 && ['variance-review', 'matched'].includes(settlement.status)).map((settlement) => <option key={settlement.id} value={settlement.id}>{settlement.settlementReference} · ₹{settlement.taxWithheldAmount.toLocaleString('en-IN')}</option>)}</select></label><label>Tax type<select name="taxType"><option value="tds">TDS</option><option value="tcs">TCS</option></select></label><label>Period from<input name="periodFrom" type="date" defaultValue="2026-07-01" required /></label><label>Period to<input name="periodTo" type="date" defaultValue="2026-07-30" required /></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required /></label><label>Certificate reference<input name="certificateReference" placeholder="TDS-CERT-100" required /></label><label>Challan reference<input name="challanReference" placeholder="Optional challan" /></label><button className="button button--primary" disabled={busy || !onCreateWithholdingEvidence}>Prepare tax evidence</button>
      </form>
      <div><strong><CheckCircle2 size={15} /> Withholding review queue</strong>{revenue.retailSettlementWithholdingEvidence.slice(0, 10).map((record) => <div className="retail-returns-workbench__history-list" key={record.id}><div><strong>{record.status} · {record.taxType.toUpperCase()} · ₹{record.amount.toLocaleString('en-IN')}</strong><small>{record.certificateReference} · {record.periodFrom} to {record.periodTo}</small></div>{record.status === 'prepared' && record.requestedBy !== activeActorId ? <EvidenceActionForm label="Independent withholding-review evidence" placeholder="Actual certificate, challan, and settlement reference" buttonLabel="Approve tax evidence" busy={busy} disabled={!onDecideWithholdingEvidence} onSubmit={(evidence) => void show(() => onDecideWithholdingEvidence!({ id: record.id, decision: 'approved', evidence, expectedVersion: record.version }), 'TDS/TCS evidence approved; settlement closure gate updated.')} /> : null}</div>)}</div>
    </div>
    <div className="retail-returns-workbench__history-list">{activeOrders.map((order) => { const handoffCandidates = revenue.salesOrders.filter((salesOrder) => salesOrder.status !== 'cancelled'); const locationCandidates = revenue.stockLocations.filter((location) => location.active); return <div key={order.id}><div><strong>{order.orderNumber} · {order.status}</strong><small>{order.lines.length} lines · ₹{order.totalAmount.toLocaleString('en-IN')} · {order.localSalesOrderId ? `handed off to ${revenue.salesOrders.find((salesOrder) => salesOrder.id === order.localSalesOrderId)?.number ?? order.localSalesOrderId}` : 'no local sales-order handoff'} · {order.inventoryReservationIds?.length ? `${order.inventoryReservationIds.length} stock reservation(s)` : 'stock not reserved'} · {order.rtoReference ?? 'no RTO reference'}</small></div>{!order.localSalesOrderId && ['imported', 'confirmed'].includes(order.status) ? <form onSubmit={(event) => void submit(event, async (data) => show(onHandoffOrder ? () => onHandoffOrder({ orderId: order.id, salesOrderId: String(data.get('salesOrderId')), evidence: String(data.get('evidence')), expectedVersion: order.version }) : undefined, 'Remote order handed off to the local sales-order fulfilment path.'))}><select name="salesOrderId" aria-label={`Sales order for ${order.orderNumber}`} required><option value="">Select local sales order</option>{handoffCandidates.map((salesOrder) => <option key={salesOrder.id} value={salesOrder.id}>{salesOrder.number} · ₹{salesOrder.taxPreview.grandTotal.toLocaleString('en-IN')}</option>)}</select><input name="evidence" placeholder="Actual order, GST, and SKU reconciliation reference" aria-label="Handoff evidence" minLength={4} required /><button type="submit" disabled={busy || !onHandoffOrder}>Handoff</button></form> : null}{order.status === 'confirmed' && order.localSalesOrderId && !order.inventoryReservationIds?.length ? <form onSubmit={(event) => void submit(event, async (data) => show(onReserveOrder ? () => onReserveOrder({ orderId: order.id, locationId: String(data.get('locationId')), evidence: String(data.get('reservationEvidence')), expectedVersion: order.version }) : undefined, 'Local stock reserved atomically; the remote order may now enter fulfilment.'))}><select name="locationId" aria-label={`Dispatch stock location for ${order.orderNumber}`} required><option value="">Select dispatch location</option>{locationCandidates.map((location) => <option key={location.id} value={location.id}>{location.code} · {location.name}</option>)}</select><input name="reservationEvidence" placeholder="Actual stock-count or scan evidence reference" aria-label="Reservation evidence" minLength={4} required /><button type="submit" disabled={busy || !onReserveOrder || !locationCandidates.length}>Reserve stock</button></form> : null}{suggestedNext(order).length ? <form className="retail-evidence-action" onSubmit={(event) => void submit(event, async (data) => { const status = String(data.get('status')) as RetailCommerceOrder['status']; await show(onTransitionOrder ? () => onTransitionOrder({ id: order.id, status, evidence: String(data.get('evidence')), rtoReference: String(data.get('rtoReference')) || undefined, expectedVersion: order.version }) : undefined, `Remote order moved to ${status}.`); })}><label>Next local status<select name="status" aria-label={`Next status for ${order.orderNumber}`} required>{suggestedNext(order).map((status) => <option key={status} value={status}>{status.replaceAll('-', ' ')}</option>)}</select></label><label>Received provider/custody evidence<input name="evidence" placeholder="Actual callback, scan, or cancellation reference" minLength={4} required /></label><label>RTO reference (required for RTO)<input name="rtoReference" placeholder="Actual carrier or marketplace RTO reference" /></label><button type="submit" disabled={busy || !onTransitionOrder}>Record status evidence</button></form> : null}</div>; })}</div>
    <div className="retail-exchange-form__row">
       <form onSubmit={(event) => void submit(event, async (data) => show(onCreateConformanceCase ? () => onCreateConformanceCase({ connectorId: String(data.get('connectorId')), capability: String(data.get('capability')) as CreateRetailCommerceConformanceCaseInput['capability'], suiteName: String(data.get('suite')), suiteVersion: String(data.get('version')), scenario: String(data.get('scenario')) }) : undefined, 'Provider capability conformance case planned.'))}><strong><ShieldCheck size={15} /> Provider capability conformance</strong><label>Connector<select name="connectorId" required>{revenue.retailCommerceConnectors.map((connector) => <option key={connector.id} value={connector.id}>{connector.code} · {connector.channel}</option>)}</select></label><label>Capability<select name="capability" required><option value="catalog-push">Catalog push</option><option value="inventory-push">Inventory push</option><option value="order-pull">Order pull</option><option value="settlement-pull">Settlement pull</option></select></label><label>Suite<input name="suite" defaultValue="ONDC Retail Seller" required /></label><label>Version<input name="version" defaultValue="1.0" required /></label><label>Scenario<input name="scenario" defaultValue="capability sandbox replay" required /></label><button className="button button--primary" disabled={busy || !onCreateConformanceCase}>Plan conformance</button></form>
       <div><strong>Certification queue</strong>{revenue.retailCommerceConformanceCases.slice(0, 8).map((item) => <div className="retail-returns-workbench__history-list" key={item.id}><div><strong>{item.suiteName} · {item.result}</strong><small>{item.capability ?? 'legacy capability record'} · {item.scenario}</small></div>{item.result === 'planned' && item.preparedBy !== activeActorId ? <form onSubmit={(event) => void submit(event, async (data) => show(onRecordConformance ? () => onRecordConformance({ id: item.id, result: String(data.get('result')) as RecordRetailCommerceConformanceInput['result'], evidenceReference: String(data.get('evidenceReference')), resultChecksum: String(data.get('resultChecksum')), expectedVersion: item.version }) : undefined, 'Provider conformance evidence recorded; certification gate recalculated.'))}><select name="result" aria-label={`Conformance result for ${item.suiteName}`}><option value="passed">Passed</option><option value="failed">Failed</option><option value="blocked">Blocked</option></select><input name="evidenceReference" placeholder="Real provider sandbox evidence reference" required /><input name="resultChecksum" placeholder="Provider result SHA-256" required /><button type="submit" disabled={busy || !onRecordConformance}>Record result</button></form> : null}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <div><strong><FileCheck2 size={15} /> Purchase exception automation</strong><p className="retail-returns-workbench__settlement-intro">Normalize and scan OCR documents for confidence, GSTIN/date validity, total drift, duplicate invoice, GST, mapping and quantity exceptions before supplier-invoice conversion.</p><button type="button" className="button button--primary" disabled={busy || !onScanPurchaseExceptions || !revenue.retailPurchaseOcrDocuments.length} onClick={() => void show(() => onScanPurchaseExceptions!({}), 'OCR normalization and exception scan completed; actionable exceptions are now queued.')}>Scan all OCR documents</button></div>
      <div><strong>Exception queue</strong>{revenue.retailPurchaseExceptions.slice(0, 12).map((exception) => <div className="retail-returns-workbench__history-list" key={exception.id}><div><strong>{exception.number} · {exception.kind} · {exception.severity}</strong><small>{exception.message}</small><small>Suggested: {exception.suggestedAction}</small></div>{exception.status === 'open' && exception.requestedBy !== activeActorId ? <form className="retail-evidence-action" onSubmit={(event) => void submit(event, async (data) => { const decision = String(data.get('decision')) as ResolveRetailPurchaseExceptionInput['decision']; await show(onResolvePurchaseException ? () => onResolvePurchaseException({ id: exception.id, decision, evidence: String(data.get('evidence')), expectedVersion: exception.version }) : undefined, `Purchase exception ${decision} with accountable evidence.`); })}><label>Decision<select name="decision" aria-label={`Decision for ${exception.number}`}><option value="resolved">Resolve</option><option value="waived">Waive</option></select></label><label>Independent exception evidence<input name="evidence" placeholder="Actual source invoice or approved exception reference" minLength={4} required /></label><button type="submit" disabled={busy || !onResolvePurchaseException}>Record decision</button></form> : <em>{exception.status}</em>}</div>)}</div>
    </div>
    <div className="retail-exchange-form__row">
      <div><strong><Link2 size={15} /> Return / RTO evidence bridge</strong><p className="retail-returns-workbench__settlement-intro">Link a returned marketplace order only when a local approved return, GST credit-note pack and posted inventory receipt are all present.</p></div>
      <div>{activeOrders.filter((order) => ['returned', 'rto'].includes(order.status)).slice(0, 8).map((order) => { const localReturn = revenue.retailReturns.find((candidate) => candidate.retailSaleNumber === order.orderNumber || candidate.retailSaleId === order.localSalesOrderId); const creditNote = localReturn ? revenue.retailCreditNoteReconciliations.find((candidate) => candidate.retailReturnId === localReturn.id) : undefined; const inventoryEvidence = localReturn ? revenue.inventoryLedger.find((entry) => entry.reference === localReturn.number)?.reference : undefined; const linked = Boolean(order.retailReturnId); return <div className="retail-returns-workbench__history-list" key={order.id}><div><strong>{order.orderNumber} · {order.status}</strong><small>{linked ? 'return, GST and inventory evidence linked' : 'awaiting local evidence bridge'}</small></div>{linked ? <em>Linked</em> : <button type="button" disabled={busy || !onLinkReturn || !localReturn || !creditNote || !inventoryEvidence} onClick={() => void show(() => onLinkReturn!({ orderId: order.id, retailReturnId: localReturn!.id, creditNoteReconciliationId: creditNote!.id, inventoryEvidenceReference: inventoryEvidence!, expectedVersion: order.version }), 'Marketplace return linked to local inventory and GST credit evidence.')}>Link evidence</button>}</div>; })}</div>
    </div>
    {notice ? <p className="retail-returns-workbench__notice" role="status">{notice}</p> : null}
  </section>;
}
